import {
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  OnDestroy,
  computed,
  effect,
  inject,
  signal,
  viewChild
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MPageService } from '@clinicaloffice/mpage-developer';
import { HelpModal } from '../../components/help-modal/help-modal';
import { ParameterLibraryService } from '../../services/parameter-library.service';
import { ServiceRegistryService } from '../../services/service-registry.service';
import { UserConfigService } from '../../services/user-config.service';

@Component({
  selector: 'app-config-editor',
  standalone: true,
  imports: [FormsModule, HelpModal],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './config-editor.html',
  styleUrl: './config-editor.scss'
})
export class ConfigEditor implements AfterViewInit, OnDestroy {
  private paramLibrary = inject(ParameterLibraryService);
  private registry = inject(ServiceRegistryService);
  private userConfig = inject(UserConfigService);
  public MPage = inject(MPageService);

  importMessage = signal<string | null>(null);
  dbSaving = signal(false);
  dbLoading = signal(false);

  selectedSection = signal<'parameters' | 'services' | 'bundle'>('bundle');
  viewMode = signal<'code' | 'tree'>('code');
  editorContent = signal<string>('');
  originalContent = signal<string>('');
  parseError = signal<string | null>(null);
  hasChanges = computed(() => this.editorContent() !== this.originalContent());
  statusMessage = signal<string | null>(null);
  helpOpen = signal(false);
  sectionLabel = computed(() => this.sections.find(s => s.value === this.selectedSection())?.label ?? '');

  treeContainer = viewChild<ElementRef>('treeContainer');
  private editorInstance: any = null;

  sections = [
    { label: 'Parameter Library', value: 'parameters' as const },
    { label: 'Service Registry', value: 'services' as const },
    { label: 'Full Bundle', value: 'bundle' as const }
  ];

  constructor() {
    // Re-initialize tree editor when switching to tree mode or content changes
    effect(() => {
      const mode = this.viewMode();
      const content = this.editorContent();
      if (mode === 'tree') {
        setTimeout(() => this.initTreeEditor(), 0);
      }
    });
  }

  ngAfterViewInit(): void {
    this.loadSection('bundle');
  }

  ngOnDestroy(): void {
    if (this.editorInstance) {
      this.editorInstance.destroy();
    }
  }

  loadSection(section: 'parameters' | 'services' | 'bundle'): void {
    this.selectedSection.set(section);
    this.statusMessage.set(null);
    this.parseError.set(null);

    let content = '';
    switch (section) {
      case 'parameters': {
        const stored = localStorage.getItem('dwsv_user_types');
        content = stored ? this.tryFormat(stored) : '[]';
        break;
      }
      case 'services': {
        const stored = localStorage.getItem('dwsv_user_services');
        content = stored ? this.tryFormat(stored) : '[]';
        break;
      }
      case 'bundle': {
        const bundle = {
          version: 3,
          parameterTypes: this.paramLibrary.exportAllTypes(),
          services: this.registry.allServices()
        };
        content = JSON.stringify(bundle, null, 2);
        break;
      }
    }

    this.editorContent.set(content);
    this.originalContent.set(content);
  }

  onEditorChange(content: string): void {
    this.editorContent.set(content);
    this.statusMessage.set(null);
    try {
      JSON.parse(content);
      this.parseError.set(null);
    } catch (e: any) {
      this.parseError.set(e.message || 'Invalid JSON');
    }
  }

  formatJson(): void {
    try {
      const parsed = JSON.parse(this.editorContent());
      this.editorContent.set(JSON.stringify(parsed, null, 2));
      this.parseError.set(null);
    } catch (e: any) {
      this.parseError.set(e.message || 'Invalid JSON');
    }
  }

  copyToClipboard(): void {
    navigator.clipboard.writeText(this.editorContent());
    this.statusMessage.set('Copied to clipboard');
    setTimeout(() => this.statusMessage.set(null), 2000);
  }

  applyChanges(): void {
    let parsed: any;
    try {
      parsed = JSON.parse(this.editorContent());
    } catch (e: any) {
      this.parseError.set(e.message || 'Invalid JSON');
      return;
    }

    const section = this.selectedSection();
    switch (section) {
      case 'parameters':
        this.paramLibrary.replaceCustomTypes(parsed);
        break;
      case 'services':
        this.registry.replaceCustomServices(parsed);
        break;
      case 'bundle':
        if (parsed.parameterTypes) {
          this.paramLibrary.importTypes(parsed.parameterTypes);
        }
        if (parsed.services) {
          this.registry.replaceCustomServices(parsed.services);
        }
        break;
    }

    this.originalContent.set(this.editorContent());
    this.statusMessage.set('Changes applied successfully');
    setTimeout(() => this.statusMessage.set(null), 3000);
  }

  resetAll(): void {
    this.paramLibrary.resetAll();
    this.registry.resetAll();
    this.loadSection(this.selectedSection());
    this.statusMessage.set('All settings reset to defaults');
    setTimeout(() => this.statusMessage.set(null), 3000);
  }

  exportBundle(): void {
    const bundle = {
      version: 3,
      parameterTypes: this.paramLibrary.exportAllTypes(),
      services: this.registry.allServices()
    };
    const json = JSON.stringify(bundle, null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'dwsv-bundle.json';
    a.click();
    URL.revokeObjectURL(url);
  }

  importBundle(event: Event): void {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result as string);

        if (data.version) {
          const paramResult = this.paramLibrary.importTypes(data.parameterTypes || []);
          const serviceResult = this.registry.importServices(JSON.stringify(data.services || []));
          this.importMessage.set(
            `Imported ${serviceResult.imported} services, ${paramResult.imported} parameters, skipped ${serviceResult.skipped + paramResult.skipped}`
          );
        } else if (Array.isArray(data)) {
          const result = this.registry.importServices(JSON.stringify(data));
          this.importMessage.set(`Imported ${result.imported}, skipped ${result.skipped}`);
        } else {
          this.importMessage.set('Error: Unrecognized format');
        }

        this.loadSection(this.selectedSection());
        setTimeout(() => this.importMessage.set(null), 3000);
      } catch {
        this.importMessage.set('Error: Invalid JSON file');
        setTimeout(() => this.importMessage.set(null), 3000);
      }
    };
    reader.readAsText(file);
  }

  async saveToDatabase(): Promise<void> {
    this.dbSaving.set(true);
    try {
      const result = await this.userConfig.saveUserConfig();
      this.importMessage.set(result.message);
      setTimeout(() => this.importMessage.set(null), 3000);
    } catch (err: any) {
      this.importMessage.set('Error: ' + err.message);
      setTimeout(() => this.importMessage.set(null), 3000);
    } finally {
      this.dbSaving.set(false);
    }
  }

  async loadFromDatabase(): Promise<void> {
    this.dbLoading.set(true);
    try {
      const prsnlId = this.userConfig.prsnlId();
      if (prsnlId) {
        await this.userConfig.loadUserConfig(prsnlId);
      }
      this.importMessage.set('Configuration loaded from database');
      this.loadSection(this.selectedSection());
      setTimeout(() => this.importMessage.set(null), 3000);
    } catch (err: any) {
      this.importMessage.set('Error: ' + err.message);
      setTimeout(() => this.importMessage.set(null), 3000);
    } finally {
      this.dbLoading.set(false);
    }
  }

  private tryFormat(json: string): string {
    try {
      return JSON.stringify(JSON.parse(json), null, 2);
    } catch {
      return json;
    }
  }

  private async initTreeEditor(): Promise<void> {
    const container = this.treeContainer()?.nativeElement;
    if (!container) return;

    if (this.editorInstance) {
      this.editorInstance.destroy();
      this.editorInstance = null;
    }

    let parsed: any;
    try {
      parsed = JSON.parse(this.editorContent());
    } catch {
      return;
    }

    try {
      const vje = await import('vanilla-jsoneditor');
      const EditorClass = vje.JSONEditor as any;

      this.editorInstance = new EditorClass({
        target: container,
        props: {
          content: { json: parsed },
          mode: 'tree',
          readOnly: false,
          mainMenuBar: true,
          navigationBar: true,
          onChange: (updatedContent: any) => {
            try {
              if (updatedContent.json !== undefined) {
                const text = JSON.stringify(updatedContent.json, null, 2);
                this.editorContent.set(text);
                this.parseError.set(null);
              } else if (updatedContent.text !== undefined) {
                this.editorContent.set(updatedContent.text);
                try {
                  JSON.parse(updatedContent.text);
                  this.parseError.set(null);
                } catch (e: any) {
                  this.parseError.set(e.message);
                }
              }
            } catch {
              // Ignore change errors during editing
            }
          }
        }
      });
    } catch {
      container.innerHTML = `<pre style="padding:12px;overflow:auto;max-height:100%">${this.editorContent()}</pre>`;
    }
  }
}
